\label{def:deltainst}
Given a temporal network $T$, a temporal motif~$M$,
and a value $\delta\in \mathbb{R}^+$
corresponding to a \emph{time-interval length}, a \emph{time-ordered} sequence
$S=\langle(x_1',y_1',t_1'),\dots,(x_\ell',y_\ell',t_\ell')\rangle$
of $\ell$ unique temporal edges of $T$ is a \emph{$\delta$-instance}
of the temporal motif $M=\langle(x_1,y_1),\dots,\allowbreak(x_\ell,y_\ell)\rangle$ if:


\vspace{1mm}
\noindent
(1) there exists a bijection $h$ from the vertices appearing in $S$
	to the vertices of $M$,
	with $h(x_i') = x_i $ and $h(y_i')=y_i$, and $i \in [\ell]$;


\vspace{1mm}
\noindent
(2) the edges of $S$ occur within $\delta$ time; i.e., $t_\ell' -t_1' \le \delta$.

Let $\mathcal{S}_{T}=\{S : S \text{ is a } \delta\text{-instance of } M \text{ in } T\}$
be the \emph{set of $\delta$-instances of a motif $M$}
for a given time-interval length~$\delta$.

\caption{\texttt{ProbPeel}\xspace}\label{alg:kepsilonapproxsampling}
\KwIn{$T=(V_T,E_T), M , \delta\in \mathbb{R}^+, \tau, \xi>0, \varepsilon >0, \eta \in (0,1)$.}
\KwOut{$W$.}
$W_1 \gets V_T$; $i\gets 1$\label{algsampl:inititeration}\;
\While{$W_i \neq \emptyset$\label{algsampl:mainLoop}}{

	$r_i \gets \mathtt{GetBound}(W_{i}, \varepsilon, \eta/2^{i})$\label{algsampl:boundSamples}\;
	$\mathcal{D}=\{T_1,\dots,T_{r_i}\} \gets \mathcal{A}^{r_i}(T[W_i])$\label{algsampl:getSamples}\;


	$\estimateTemporalDegreeWeight{W_i}{w_1},\dots,\estimateTemporalDegreeWeight{W_i}{w_{|W_i|}}\gets \mathtt{GetEstimates}(W_i, \mathcal{D})$\label{algsampl:computeEstimates}\;
	$\hat{\tau}(W_i)\gets 1/k \sum_{w\in W_i} \estimateTemporalDegreeWeight{W_i}{w}$\label{algsampl:estimateTotalCount}\;





	$L(W_i)\gets\left\{w\in W_i : \estimateTemporalDegreeWeight{W_i}{w}\le k(1+\xi) \hat{\tau}(W_i)/|W_i|\right\}$\label{algsampl:peelNodes}\;
	$W_{i+1} \gets W_i\setminus L(W_i)$; $i\gets i+1$\label{algsampl:setNextIt}\;




}
\KwRet{$W=arg\,max_{j=1,\dots,i}\{\hat{\tau}(W_j)/|W_j|\}$;\label{algsampl:return}}

\begin{equation}
	\estimateTemporalDegreeWeightPrime{W}{w}{T'} = \sum\nolimits_{S \in \mathcal{S}_{{T}'}:w\in S} \tau(S)/p_S,\label{eq:prestoEstH}
\end{equation}

\label{lemma:ratioSampling}

With probability at least $1-\eta$, \texttt{ProbPeel}\xspace achieves a 

$\frac{(1-\varepsilon)^2}{k(1+\xi)(1+\varepsilon)^2}$-approximation ratio for the {TMDS}\xspace~problem.

