\label{corol:sampleSize}
	Let $T[W_i]$ be the induced temporal network by $W_i$ at an arbitrary iteration  $i$ of Algorithm~\ref{alg:kepsilonapproxsampling}, given $\varepsilon>0, \eta/2^i>0,q>1$ if $r_i\ge \left(\frac{\Delta_{T[W_i]}}{(q-1)\delta}-1\right) \frac{1}{(1+\varepsilon)\ln(1+\varepsilon)-\varepsilon}\ln\left(\frac{2|W_i|}{\eta/2^i}\right)$ then $\estimateTemporalDegreeWeight{W_i}{w}\in(1\pm\varepsilon)\temporalDegreeWeight{W_i}{w}$ simultaneously for each $w\in W_i$ 

	with probability  $>1-\eta/2^i$.

\sloppy{
The proof is identical and directly follows from the guarantees obtained in~\cite[Theorem 3.4., extended arXiv version]{Sarpe2021} combined with a union bound. Fix an arbitrary vertex $w\in W_i$ and a sample $T'\subseteq W_i$, then from Lemma~\ref{lemma:unbiasedness} the estimator $\estimateTemporalDegreeWeightPrime{W_i}{w}{T'}$ is unbiased where under the sampling algorithm \texttt{PRESTO-A} we set $p_S = \tfrac{q\delta - \Delta_S}{\Delta_{T[W_i]}}$ where $\Delta_S$ is the duration of each $\delta$-instance $S\in \mathcal{S}_{W_i}$ and $\Delta_{T[W_i]} = t_{|E_T[W_i]|-\ell}-t_\ell + c\delta$ where $t_i$ denotes the timestamp of the $i$-th edge (of $E_T[W_i]$) assuming that such edges are sorted by increasing  timestamps. This implies that the bound on the variance of such estimator is the same as~\cite[Lemma 3.2., extended arXiv version]{Sarpe2021} where the global motif count is replaced with the temporal motif degree, i.e., $\mathbb{E}[\estimateTemporalDegreeWeightPrime{W_i}{w}{T'}^2] \le \frac{\temporalDegreeWeight{W_i}{w}^2 \Delta_{T[W_i]} }{ (c-1)\delta}$. Using~\cite[Theorem 3.4., extended arXiv version]{Sarpe2021} for an arbitrary vertex $w\in W_i$ it holds, that if $r_i \ge \left(\frac{\Delta_{T[W_i]}}{(q-1)\delta}-1\right) \frac{1}{(1+\varepsilon)\ln(1+\varepsilon)-\varepsilon}\ln\left(\frac{2}{\eta/2^i}\right)$ then
$\mathbb{P}[|\estimateTemporalDegreeWeight{W}{w}-\temporalDegreeWeight{W}{w}| \ge \varepsilon\temporalDegreeWeight{W}{w}] \le \eta/2^i$.
The final claims from a direct application of the union bound over all vertices $w\in W_i$.}

\caption{\texttt{HybridPeel}\xspace}\label{alg:hybridpeel}
\KwIn{$T=(V_T,E_T), M , \delta\in \mathbb{R}^+, \tau, \xi>0, \varepsilon >0, \eta \in (0,1), J\ge1$.}
\KwOut{$W$.}
$W_1 \gets V_T$\;
\For{$(i\gets 1,\dots,J) \land (W_i \neq \emptyset)$\label{alghyb:mainLoop}}{
	$r_i \gets \mathtt{GetBound}(W_{i}, \varepsilon, \eta/J)$\label{alghyb:boundSamples}\;
	$\mathcal{D}=\{T_1,\dots,T_{r_i}\} \gets \mathcal{A}^{r_i}(T[W_i])$\label{alghyb:getSamples}\;
	$\estimateTemporalDegreeWeight{W_i}{w_1},\dots,\estimateTemporalDegreeWeight{W_i}{w_{|W_i|}}\gets \mathtt{GetEstimates}(W_i, \mathcal{D})$\label{alghyb:computeEstimates}\;
	$\hat{\tau}(W_i)\gets 1/k \sum_{w\in W_i} \estimateTemporalDegreeWeight{W_i}{w}$\label{alghyb:estimateTotalCount}\;
	$L(W_i)\gets\left\{w\in W_i : \estimateTemporalDegreeWeight{W_i}{w}\le k(1+\xi) \hat{\tau}(W_i)/|W_i|\right\}$\label{alghyb:peelNodes}\;
	$W_{i+1} \gets W_i\setminus L(W_i)$; $i\gets i+1$\label{alghyb:setNextIt}\;
}
$W' \gets $ \texttt{Greedy}\xspace($T[W_{J+1}], M, \delta, \tau$)\label{alghyb:callGreedyPeel}\;
\KwRet{$W=arg\,max_{j=1,\dots,J}\{\hat{\tau}(W_j)/|W_j|, \ensuremath{\rho}\xspace(W')\}$.\label{alghyb:return}}

\begin{align}
		&k(1+\xi)(1+\varepsilon) \frac{\tau(W')}{|W'|} \ge k(1+\xi)\frac{\hat{\tau}(W')}{|W'|} \ge \estimateTemporalDegreeWeight{W'}{v} \ge (1-\varepsilon)\temporalDegreeWeight{W^*}{v}\nonumber\\



		& \ge (1-\varepsilon) \frac{\tau(W^*)}{|W^*|} \Leftrightarrow \frac{\tau(W')}{|W'|} \ge \frac{(1-\varepsilon)}{k(1+\xi)(1+\varepsilon)} \frac{\tau(W^*)}{|W^*|}. \label{eq:boundWprime}
	\end{align}

\caption{\texttt{Exact}\xspace}\label{alg:MinCutExact}
\KwIn{$T=(V_T,E_T), M , \delta\in \mathbb{R}^+, \tau$.}
\KwOut{$W^*$ optimal solution to Problem~\ref{probl:denseMotif}.}
$\mathcal{S} \gets \{S: S \text{ is } \delta\text{-instance of } M \text{ in } T\}$\label{alglineExact:enumerateInst}\;
\lIf{$\mathcal{S} = \emptyset$}{\KwRet{$\emptyset$}}
$Z \gets \mathtt{BuildGraph}(T,\mathcal{S})$\label{alglineExact:buildZ}\;
$a\gets 0; b \gets \sum_{S\in \mathcal{S}} \tau(S);\tau_{\min}\gets\min_{S\in\mathcal{S}}\{\tau(S)\}$\label{alglineExact:initab}\;
$\zeta \gets (b+a)/2$\label{alglineExact:initZeta}\;
\While{$b-a \ge \frac{\tau_{\min}}{n(n-1)}$\label{alglineExact:mainwhile}}{
	$(\mathsf{S},\mathsf{Z}) \gets \mathtt{MinCut}(s,z,Z,w_{Z,\zeta})$\label{alglineExact:mincut}\;
	\lIf{$\mathsf{S} = \{s\}$}{$b\gets \zeta$\label{alglineExact:onlyS}}
	\Else{
		$a\gets \zeta$;
		$V' \gets \mathsf{S} \cap V_T$\label{alglineExact:updateSol}\;
	}
	$\zeta \gets (b+a)/2$\label{alglineExact:biseczeta}\;
}
\KwRet{$W^* \gets  V'$\label{alglineExact:returnOPT}}\;

\begin{align}
		C(\mathsf{S}',\mathsf{Z}') 
		& = C(\{s\}, V_\mathcal{H}\cap \mathsf{Z}')+ C(\mathsf{S}'\cap V_T, \{t\})\nonumber\\
		& = \sum_{v_H\in V_\mathcal{H}\cap \mathsf{Z}'} \tau(V_H) + 
		\sum_{v\in \mathsf{S}'\cap V_T}  \zeta  \label{eq:zetaIneq-a} \\
		& = \sum_{v_H\in V_\mathcal{H}} \tau(V_H) - 
		\sum_{v_H\in V_\mathcal{H} \cap \mathsf{S}'} \left(\tau(V_H) - \zeta |V'|\right)\label{eq:zetaIneq-b}\\
		& = \tau(V_T) - \left(\tau(V') - \zeta |V'|\right) \label{eq:zetaIneq}
	\end{align}

\begin{equation}\label{eq:countHInst}
		\!\!\!\sum_{v_{H =(V_H,E_H)}\in V_\mathcal{H}'}\!\!\! \tau(V_H) = 
		\sum_{v_H \in V_\mathcal{H}'} \sum_{S\in \mathcal{S}_{V_H}}\tau(S) = 
		\!\!\!\sum_{S\in \mathcal{S}_{\cup_{v_H\in V_\mathcal{H}'} V_H}} \!\!\!\tau(S).
	\end{equation}

\caption{\texttt{Greedy}\xspace}\label{alg:kapprox}
\KwIn{$T=(V_T,E_T), M , \delta\in \mathbb{R}^+, \tau$.}
\KwOut{$W$.}
$\mathcal{S} \gets \{S: S \text{ is } \delta\text{-instance of } M \text{ in } T\}$\label{alglinekapp:enumerateInst}\;
\lIf{$\mathcal{S} = \emptyset$}{\KwRet{$\emptyset$}}
$\mathcal{S}_n \gets \mathcal{S}$; $W_n \gets V$\label{alglinekapp:initSol}\;
\For{$i\gets n,\dots,k+1$\label{alglinekapp:mainLoop}}{
	$v_{\min}\gets arg\,min_{v\in W_i} \{\temporalDegreeWeight{W_i}{v}\}$\label{alglinekapp:getMinNode}\;
	$\mathcal{S}_{i-1} \gets \mathcal{S}_i \setminus \{S : v_{\min}\in S, S \in \mathcal{S}_i\}$\label{alglinekapp:updateInst}\;
	$W_{i-1}\gets W_i\setminus \{v_{\min}\}$\label{alglinekapp:updateNodeSet}\;
}
\KwRet{$W \gets  arg\,max_{i=k,\dots,n} \{ \ensuremath{\rho}\xspace(W_i)\}$\label{alglinekapp:retMaxSol}}\;

\begin{equation}
		\frac{\tau(W^*)}{|W^*|} = \frac{\sum_{v'\in W^*} \temporalDegreeWeight{W^*}{v'}}{k|W^*|} \ge \frac{\sum_{v'\in W^*\setminus \{v\}} \temporalDegreeWeight{W^*\setminus\{v\}}{v'}}{k(|W^*|-1)}.
	\end{equation}

\begin{align*}

	&\ensuremath{\mathcal{O}}\xspace\!\left(m\hat{m}^{(\ell-1)} +   n\right. \left.\log n +  \sum_{i=1}^n (\log n + k|\mathcal{H}(v)|\log(|\mathcal{H}_{\max}|))\right)=\\
	&\ensuremath{\mathcal{O}}\xspace\!\left(m\hat{m}^{(\ell-1)} + n\log n + k^2|\mathcal{H}|\log(|\mathcal{H}_{\max}|)\right).

\end{align*}

\caption{\texttt{Batch}\xspace}\label{alg:batchpeel}
\KwIn{$T=(V_T,E_T), M , \delta\in \mathbb{R}^+, \tau, \xi>0$.}
\KwOut{$W$.}
$\mathcal{S} \gets \{S: S \text{ is } \delta\text{-instance of } M \text{ in } T\}$\label{algbatchPeel:enumInst}\;
\lIf{$\mathcal{S} = \emptyset$}{\KwRet{$\emptyset$}}

$W,W' \gets V$\label{algbatchPeel:initNodeSets}\;
\While{$W' \neq \emptyset$\label{algbatchPeel:mainLoop}}{

	$L(W')\gets\{v\in W' : \temporalDegreeWeight{W'}{v} \le k(1+\xi) \tau(W')/|W'|\}$\label{algbatchPeel:smallNodes}\;
	$W' \gets W'\setminus L(W')$\label{algbatchPeel:updateNodeSet}\;
	\If{$\ensuremath{\rho}\xspace(W') \ge \ensuremath{\rho}\xspace(W)$\label{algbatchPeel:updateBestSol}}
	{
		$W\gets W'$\;
	}
}
\KwRet{$W$.}

\begin{align*}

	&\ensuremath{\mathcal{O}}\xspace\!\left(m\hat{m}^{(\ell-1)} + \frac{(1+\xi) n}{\xi} + k^2|\mathcal{H}|\log(|\mathcal{H}_{\max}|)\right).
\end{align*}

